FLATS = ["A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab"]
FLAT_TONICS = {"F", "Bb", "Eb", "Ab", "Db", "Gb", "d", "g", "c", "f", "bb", "eb"}
STEPS = {"m": 1, "M": 2, "A": 3}


class Scale:
    def __init__(self, tonic):
        self.tonic = tonic[0].upper() + tonic[1:]
        self.notes = FLATS if tonic in FLAT_TONICS else SHARPS
        if self.tonic in self.notes:
            self.start = self.notes.index(self.tonic)
        elif self.tonic in SHARPS:
            self.start = SHARPS.index(self.tonic)
        elif self.tonic in FLATS:
            self.start = FLATS.index(self.tonic)
        else:
            raise ValueError("invalid tonic")

    def chromatic(self):
        return [self.notes[(self.start + i) % 12] for i in range(12)]

    def interval(self, intervals):
        position = self.start
        result = [self.notes[position]]
        for step in intervals:
            if step not in STEPS:
                raise ValueError("invalid interval")
            position = (position + STEPS[step]) % 12
            result.append(self.notes[position])
        return result
